static void invalidate(Rect r){if(r.w<=0||r.h<=0)return;if(!damaged){damage=r;damaged=1;}else{int x=min(damage.x,r.x),y=min(damage.y,r.y);damage.w=max(damage.x+damage.w,r.x+r.w)-x;damage.h=max(damage.y+damage.h,r.y+r.h)-y;damage.x=x;damage.y=y;}}
