/* Subtract opaque windows before drawing lower layers. Covered pixels are
   never copied from the desktop or from hidden application surfaces. */
static void compose(Rect area,int p){if(area.w<=0||area.h<=0)return;for(;p>=0;p--){int id=order[p];Window *w=&windows[id];if(w->minimized)continue;int left=max(area.x,w->x),top=max(area.y,w->y),right=min(area.x+area.w,w->x+w->w+5),bottom=min(area.y+area.h,w->y+w->h+5);if(left>=right||top>=bottom)continue;
 compose((Rect){area.x,area.y,area.w,top-area.y},p-1);compose((Rect){area.x,bottom,area.w,area.y+area.h-bottom},p-1);compose((Rect){area.x,top,left-area.x,bottom-top},p-1);compose((Rect){right,top,area.x+area.w-right,bottom-top},p-1);g_clip((Rect){left,top,right-left,bottom-top});g_fill(w->x+w->w,w->y,5,w->h+5,0x4b5c69);g_fill(w->x,w->y+w->h,w->w,5,0x4b5c69);g_blit(WINDOW_CACHE(id),w->w,w->x,w->y,w->w,w->h,0,0);return;}g_clip(area);g_blit(DESKTOP_CACHE,GUI_WIDTH,0,0,GUI_WIDTH,GUI_HEIGHT,0,0);}

static int desktop_hit(int x,int y){if(inside(x,y,GUI_WIDTH-132,50,124,80))return -2;if(inside(x,y,GUI_WIDTH-132,152,124,80))return -3;if(inside(x,y,GUI_WIDTH-132,254,124,80))return -4;if(inside(x,y,GUI_WIDTH-132,GUI_HEIGHT-118,124,85))return -5;for(int i=desk_count-1;i>=0;i--){int n=desk_nodes[i];if(inside(x,y,desk_x[n]-8,desk_y[n]-7,116,80))return n;}return -1;}
static int hit_window(int x,int y){for(int p=count-1;p>=0;p--){int id=order[p];Window *w=&windows[id];if(!w->minimized&&inside(x,y,w->x,w->y,w->w,w->h))return id;}return -1;}
static int files_hit(Window *w,int x,int y){x-=w->x;y-=w->y;if(x<142||x>w->w-12||y<106||y>=w->h-28)return -1;int list[VFS_NODES],n=file_list(w,list),row=(y-106)/28+w->first;return row<n?list[row]:-1;}
static int drop_folder(int x,int y){if(y<31)return -1;int id=hit_window(x,y);if(id>=0){Window *w=&windows[id];if(w->app!=FILES)return -1;int xx=x-w->x,yy=y-w->y;if(xx<137&&yy>=93&&yy<315){const char *paths[]={"/home/user","/home/user/Desktop","/home/user/Documents","/Applications","/boot","/home/user/Trash"};return vfs_lookup(paths[(yy-93)/37]);}if(xx<142||yy<106||yy>=w->h-28)return -1;int n=files_hit(w,x,y);return n>=0?(nodes[n].dir?n:-1):w->folder;}int n=desktop_hit(x,y);if(n==-2)return vfs_lookup("/home/user");if(n==-3||n==-4)return -1;if(n==-5)return vfs_lookup("/home/user/Trash");if(n>=0&&n!=press_node)return nodes[n].dir?n:-1;return vfs_lookup("/home/user/Desktop");}
static void file_press(int n,int id,int x,int y,u32 time){press_node=n;press_owner=id;press_x=x;press_y=y;press_double=last_node==n&&time-last_click<40;last_node=n;last_click=time;}
static void file_release(void){int n=press_node;press_node=-999;if(dnd){dnd=0;invalidate((Rect){dnd_x-4,dnd_y-4,150,87});if(n<0)return;int dest=dnd_target;if(dest<0||nodes[dest].readonly){notice("无法放到这里，请选择可写的文件夹。");return;}if(n==dest){notice("文件夹不能移入自身。");return;}int desktop=vfs_lookup("/home/user/Desktop");if(nodes[n].parent==desktop&&dest==desktop){desk_x[n]=max(8,min(GUI_WIDTH-154,dnd_x-30));desk_y[n]=max(45,min(GUI_HEIGHT-78,dnd_y-14));all_changed();return;}if(nodes[n].parent==dest)return;char src[VFS_PATH],to[VFS_PATH];vfs_path(n,src);vfs_path(dest,to);if(vfs_child(dest,nodes[n].name)>=0){notice("目标文件夹中已有同名项目。");return;}int result=nodes[n].readonly?vfs_copy(src,to,(u8 *)0xf00000):vfs_move(src,to);if(result<0)notice(vfs_error);else all_changed();return;}if(!press_double||n==-999)return;last_node=-999;if(n<0){const char *path=n==-2?"/home/user":n==-3?"/boot":n==-4?"/Applications":"/home/user/Trash";folder_open(vfs_lookup(path));}else if(press_owner>=0&&windows[press_owner].used&&windows[press_owner].app==FILES){focus(press_owner);command(6);}else open_node(n);}
