static void right_click(int x,int y){int user=hit_window(x,y);if(user>=0&&windows[user].app==USERAPP){focus(user);process_message(user_owner[user],(UiEvent){MSG_CONTEXT,(u32)user,x-windows[user].x,y-windows[user].y,0});return;}if(modal||y<31)return;menu=-1;press_node=-999;dnd=0;if(ime_len)ime_reset();int id=hit_window(x,y);if(id>=0){if(windows[id].app!=FILES)return;focus(id);context_node=files_hit(&windows[id],x,y);windows[id].selected=context_node;changed(id);}else{changed(gui_focus);gui_focus=-1;context_node=desktop_hit(x,y);if(context_node<0)context_node=-1;desk_selected=context_node;desktop_dirty=1;}context_open=1;context_row=-1;context_x=min(x,GUI_WIDTH-224);context_y=max(32,min(y,GUI_HEIGHT-12-context_count()*28));invalidate((Rect){0,0,GUI_WIDTH,GUI_HEIGHT});}
