static void ime_commit(const char *text,int n){if(modal==1){if(n>127-(dialog_selected?0:dialog_len))return;if(dialog_selected){dialog_len=0;dialog_selected=0;}memcpy(dialog+dialog_len,text,(u32)n);dialog_len+=n;dialog[dialog_len]=0;}else if(gui_focus>=0&&windows[gui_focus].app==TERM){char encoded[128];if(n>127)return;memcpy(encoded,text,(u32)n);encoded[n]=0;shell_text(encoded);changed(gui_focus);}else if(gui_focus>=0&&windows[gui_focus].app==USERAPP){for(int offset=0;offset<n;){u32 cp=utf_next(text,&offset);process_message(user_owner[gui_focus],(UiEvent){MSG_TEXT,(u32)gui_focus,0,0,(int)cp});}}else if(gui_focus>=0&&windows[gui_focus].app==EDIT){int id=gui_focus;Window *w=&windows[id];memcpy(undo_text[id],w->text,(u32)w->len+1);undo_len[id]=w->len;undo_caret[id]=w->caret;undo_valid[id]=1;insert(w,text,n);edit_reveal(w);changed(id);}ime_reset();}
