static Rect ime_bounds(void){int x=DIALOG_X+21,y=modal?DIALOG_Y+106:GUI_HEIGHT-118;if(!modal&&gui_focus>=0){Window *w=&windows[gui_focus];if(w->app==USERAPP)return(Rect){max(8,min(GUI_WIDTH-458,w->x+20)),max(32,min(GUI_HEIGHT-84,w->y+w->h-78)),450,64};if(w->app==TERM){u32 pos;con_snapshot(terminal,&pos);if(pos!=0xffffffffu)return(Rect){max(8,min(GUI_WIDTH-458,w->x+20+(int)(pos%80)*7)),max(32,min(GUI_HEIGHT-84,w->y+65+(int)(pos/80)*18)),450,64};}int l,c;edit_position(w,w->caret,&l,&c);int pixel=0;for(int i=edit_index(w,l,0);i<w->caret;)pixel+=g_advance(0,utf_next(w->text,&i));x=max(8,min(GUI_WIDTH-458,w->x+20+pixel-w->hscroll));y=max(32,min(GUI_HEIGHT-84,w->y+100+(l-w->scroll)*18));}return(Rect){x,y,450,64};}
