void gui_user_close(int token){int id=token&255;u32 pid=(u32)token>>8;if(id<NW&&windows[id].used&&windows[id].app==USERAPP&&user_owner[id]==pid){user_owner[id]=0;close_now(id);}}
int gui_user_scene(int token,const UiScene *scene){int id=token&255;u32 pid=(u32)token>>8;if(id>=NW||user_owner[id]!=pid||!user_scene[id]||scene->count>UI_CANVAS_COMMANDS)return S_INVALID;for(u32 i=0;i<scene->count;i++){const UiCommand *c=&((const UiCanvas *)scene)->commands[i];if((c->kind>=UI_PANEL&&(c->w<4||c->h<4))||c->kind<UI_FILL||c->kind>UI_SELECTION||c->x<0||c->x>1000||c->y<30||c->y>714||c->w<0||c->w>1000||c->h<0||c->h>714||c->text[79])return S_INVALID;}memcpy(user_scene[id],scene,4+scene->count*sizeof(UiCommand));changed(id);return 0;}

int gui_clip_read(u8 *data,u32 cap){if((u32)cliplen>cap)return S_LIMIT;memcpy(data,clipboard,(u32)cliplen);return cliplen;}
int gui_clip_write(const u8 *data,u32 size){if(size>EDIT_CAP)return S_LIMIT;memcpy(clipboard,data,size);clipboard[size]=0;cliplen=(int)size;return 0;}

int gui_user_policy(int token,u32 flags){int id=token&255;u32 pid=(u32)token>>8;if(id>=NW||user_owner[id]!=pid||flags>3)return S_INVALID;user_guard[id]=flags;return 0;}
